import{z as l,x as s,o as E,c as i,q as t,j as o,D as B,d as r,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"NBBO 构造","description":"","frontmatter":{"title":"NBBO 构造","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/nbbo-construction.md","filePath":"quant/nbbo-construction.md","lastUpdated":1791063341000}'),p={name:"quant/nbbo-construction.md"};function d(h,a,c,m,C,u){const e=s("Mermaid");return E(),i("div",null,[a[2]||(a[2]=t('<h1 id="nbbo-构造" tabindex="-1">NBBO 构造 <a class="header-anchor" href="#nbbo-构造" aria-label="Permalink to &quot;NBBO 构造&quot;">​</a></h1><div class="epigraph"><p>全国最优买卖是保护报价在共同时钟上的逐事件包络。构造细节——哪些尺寸、是否含锁定、用哪一条馈送——会改变中点，从而改变每一笔有效价差。</p><footer>—— 据 Reg NMS 对保护报价与 NBBO 的定义；对照 Hasbrouck 对综合报价的经验处理</footer></div><p><a href="/quant/ptp-gps-sync">PTP / GPS 对时</a>给出了跨所时间能否相减。<a href="/quant/market-fragmentation">市场分割</a>给出了 NBBO 的设计含义。本课的缺口是算法：输入各所保护报价事件，输出 \\((B_{\\mathrm{N}}(t),A_{\\mathrm{N}}(t))\\)。Holders 与研究人员各自实现时，常在零股、锁定交叉、过时报价、SIP 与直连之间分叉。本课写可复述的构造步骤，使有效价差与 EMO 的「外侧」有定义。不重复碎片化的质量辩论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素算法：每个事件时刻，在所有场所的当前买价里取最大，卖价里取最小。立刻遇到：场所报价是否仍有效（未过期、未停牌）、尺寸是否达到 round lot、是否允许锁交叉进入包络、直连缺失的场所用什么填充。SIP 的官方 NBBO 已经做完这些选择；自己用直连拼，必须把选择写成代码注释。缺口是：论文里「我们用 NBBO 中点」若不可复述，ES 不可比。</p><p>过时报价：某所短暂停更新，朴素包络会把一个旧的最优买价一直留下，造成虚假交叉。需要心跳与过期规则。这与序号缺口相关：增量丢了却没过期，包络是错的。</p><p><span class="marginnote">过期规则要有具体数字：比如约定某所超过 250 毫秒没有心跳或报价更新，就把它的报价从包络里摘除。若某所旧买价 10.00 一直挂着而真实早已撤销，包络会出现「买 10.00 / 卖 9.99」的假交叉，后续所有价差统计都被污染。</span></p><p>一个事件要满足什么条件才有资格进入保护包络，可以画成一道逐关检查：</p>',8)),(E(),o(A,null,{default:B(()=>[n(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%96%B0%E6%8A%A5%E4%BB%B7%E4%BA%8B%E4%BB%B6%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20B%7B%22%E6%97%B6%E9%92%9F%E5%B7%B2%E5%AF%B9%E5%87%86%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20X%5B%22%E4%B8%A2%E5%BC%83%E5%B9%B6%E8%AE%B0%E5%BD%95%E8%AF%8A%E6%96%AD%22%5D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20C%7B%22%E5%B0%BA%E5%AF%B8%E8%BE%BE%20round%20lot%20%E4%B8%94%E5%B1%9E%E4%BF%9D%E6%8A%A4%E7%B1%BB%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20Y%5B%22%E5%8F%AA%E8%BF%9B%E5%8F%AF%E4%BA%A4%E6%98%93%E6%9C%80%E4%BC%98%22%5D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20D%7B%22%E5%BA%8F%E5%8F%B7%E8%BF%9E%E7%BB%AD%E3%80%81%E6%8A%A5%E4%BB%B7%E6%9C%AA%E8%BF%87%E6%9C%9F%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20Z%5B%22%E5%88%87%E6%96%AD%E8%AF%A5%E6%89%80%E6%97%A7%E4%BB%B7%22%5D%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20E%7B%22%E5%BD%93%E5%89%8D%E5%A4%84%E4%BA%8E%E6%8B%8D%E5%8D%96%E6%97%B6%E6%AE%B5%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20F%5B%22%E6%A0%87%E8%AE%B0%E6%8B%8D%E5%8D%96%EF%BC%8C%E4%B8%8D%E6%B2%BF%E7%94%A8%E6%97%A7%E5%8C%85%E7%BB%9C%22%5D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5B%22%E6%9B%B4%E6%96%B0%E8%AF%A5%E6%89%80%E7%8A%B6%E6%80%81%E5%B9%B6%E9%87%8D%E7%AE%97%E5%8C%85%E7%BB%9C%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="保护报价-全部可见报价" tabindex="-1">保护报价 ≠ 全部可见报价 <a class="header-anchor" href="#保护报价-全部可见报价" aria-label="Permalink to &quot;保护报价 ≠ 全部可见报价&quot;">​</a></h3><p>零股、某些非保护指令、未达到规则尺寸的报价，不进保护 NBBO，但仍可成交。构造保护 NBBO 时排除它们；构造「可交易合成最优」时可以纳入。两套都应能产出，并在表头写名字。用可交易最优去评估 trade-through，会把合法的非保护成交当成违规。用保护 NBBO 去评价零售改善，会把零股改善当成了不起的价格改善。</p><p><span class="marginnote">round lot 就是交易所认定的「标准一手」股数（美股通常 100 股）。挂单量不足一手的报价不享受订单保护，所以构造保护 NBBO 要先按尺寸过滤——把零股报价一视同仁地算进包络，是初学者最常见的构造错误之一。</span></p><p><span class="marginnote">锁定（\\(B=A\\) 跨所）与交叉（\\(B\\gt A\\)）在未校准时钟上更容易出现。构造前应对时；仍出现的锁交叉应保留为状态，而不是在代码里强制 \\(B\\lt A\\) 把真实制度现象洗掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件驱动：每个场所维护当前保护买/卖及尺寸、序号、时间。事件到达（已对时）则更新该所，再重算包络。输出：NBBO、贡献场所、是否 lock/cross、保护深度（各所在最优价上的尺寸之和）。与 SIP 官方 NBBO 对照：分叉占比、分叉时差一个 tick 的占比。分叉来自延迟、来自尺寸规则、还是来自你漏买的场所，应能诊断。</p><p>中点 \\(M=(B_{\\mathrm{N}}+A_{\\mathrm{N}})/2\\) 在 lock 时仍有定义，在 cross 时几何崩溃。交叉期间有效价差应标缺失，或改用本所中点，不要输出负的报价价差当数据。开收盘拍卖期许多场所没有连续保护报价，NBBO 应标拍卖状态，而不是沿用前一连续报价。</p><h3 id="与方向分类、实现价差的接口" tabindex="-1">与方向分类、实现价差的接口 <a class="header-anchor" href="#与方向分类、实现价差的接口" aria-label="Permalink to &quot;与方向分类、实现价差的接口&quot;">​</a></h3><p>EMO 的 at-ask 是相对哪一个 \\(A\\)？保护 \\(A_{\\mathrm{N}}\\) 还是本所 \\(A\\)？必须声明。实现价差的 \\(M_{t+\\tau}\\) 必须与 \\(M_t\\) 同一构造，否则曲线形状来自中点定义漂移。多 \\(\\tau\\) 曲线在拍卖处断开，构造算法要能输出「此刻无连续 NBBO」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NBBO 是规则输出，不是自然价格。它成为暗池中点锚、订单保护参照、有效价差分母。构造偏误会系统性改写市场质量：漏掉一个经常报价的场所，价差被估宽；未过期旧报价，价差被估窄甚至交叉。这与价差分解三项无关——你改的是会计的分母。先修设计课已经警告对照 SIP 还是直连；本课把警告变成可执行的事件循环。</p><p><span class="marginnote">初学者容易把 NBBO 当成「市场真实价格」。实际上它是规则的计算输出：换一套关于零股、过期、锁交叉的选择，同一毫秒会得到不同的 NBBO，所有以中点为分母的指标——有效价差、EMO 外侧比例——都会随之整体平移。</span></p><p><span class="marginnote">不要在交叉的 NBBO 上估 <a href="/quant/roll-model">Roll</a>。Roll 需要买卖回跳的成交价；交叉的综合报价说明参照已经坏了，应回到本所成交价或等交叉解除。</span></p>',13)),(E(),o(A,null,{default:B(()=>[n(e,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TB%0A%20%20Q%5B%22%E5%90%84%E6%89%80%E4%BF%9D%E6%8A%A4%E6%8A%A5%E4%BB%B7%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20E%5B%22%E5%AF%B9%E6%97%B6%E5%90%8E%E7%9A%84%E4%BA%8B%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20E%20--%3E%20ST%5B%22%E6%AF%8F%E6%89%80%E5%BD%93%E5%89%8D%E6%8A%A5%E4%BB%B7%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20N%5B%22%E5%8C%85%E7%BB%9C%EF%BC%9Amax%20bid%2C%20min%20ask%22%5D%0A%20%20N%20--%3E%20FL%5B%22lock%20%2F%20cross%20%2F%20%E8%BF%87%E6%9C%9F%E8%AF%8A%E6%96%AD%22%5D%0A%20%20N%20--%3E%20M%5B%22%E4%BF%9D%E6%8A%A4%E4%B8%AD%E7%82%B9%22%5D%0A%20%20M%20--%3E%20ES%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E4%B8%8E%E6%96%B9%E5%90%91%E5%88%86%E7%B1%BB%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h3 id="拍卖时段应输出无连续-nbbo" tabindex="-1">拍卖时段应输出无连续 NBBO <a class="header-anchor" href="#拍卖时段应输出无连续-nbbo" aria-label="Permalink to &quot;拍卖时段应输出无连续 NBBO&quot;">​</a></h3><p>开收盘与波动再开盘，保护报价可能不存在或不应沿用前一连续口。构造器要打拍卖状态，有效价差改用集合会计。沿用旧包络会在开盘制造虚假交叉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有 SIP 的市场，构造的是「你覆盖范围内的最优」，不要叫 NBBO。欧洲最佳执行不是单一法定 NBBO。下一课 TRACE 是债券打印，没有股票式包络可拼。加密聚合最优是网站行为，不是保护报价。</p><p><span class="marginnote">自己拼的直连包络与 SIP 官方 NBBO 分叉时，应诊断缺所、尺寸规则还是延迟，而不是挑选更漂亮的一条写进论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NBBO 构造是事件驱动的保护报价包络，规则必须可复述。</li><li>保护最优与可交易最优分开输出。</li><li>过期、停牌、拍卖状态要切断包络，禁止旧报价永驻。</li><li>交叉时中点缺失，不要硬算有效价差。</li><li>与 SIP 官方序列对照，用来诊断馈送与规则，而不是偷偷选更漂亮的一条。</li><li>出处：Reg NMS 对保护报价的定义；Hasbrouck 对综合报价的使用；零股与尺寸见 O&#39;Hara, Saar and Zhong。</li></ul>',7))])}const F=l(p,[["render",d]]);export{D as __pageData,F as default};
